import {
  VStack,
  Button,
  FormControl,
  FormLabel,
  FormHelperText,
  Input,
} from "@chakra-ui/react";

const Login = () => {
  <VStack>
    <FormControl>
      <FormLabel>Username</FormLabel>
      <Input type="text" />
      <FormHelperText>Enter your username</FormHelperText>
    </FormControl>
    <FormControl>
      <FormLabel>Password</FormLabel>
      <Input type="password" />
      <FormHelperText>Enter your password</FormHelperText>
    </FormControl>
    <Button>Login</Button>
  </VStack>;
};

export default Login;
